package vn.vht.qtkhcn.identity.repository; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import vn.vht.qtkhcn.identity.domain.*; public interface UserAppRepository extends JpaRepository<UserApp,UserAppId>{@Query("select x from UserApp x join fetch x.app where x.user.id=:userId") List<UserApp> findByUserId(@Param("userId") UUID userId); void deleteByUserId(UUID userId);}
